/**
 * Typed companion to `sidebar-structure.json` (generated by the converter in
 * tools/asciidoc-to-mdx): the shape contract and the mapping to Starlight's
 * sidebar config. astro.config.ts just imports the ready `sidebar`.
 */
import type starlight from "@astrojs/starlight";
import sidebarStructure from "./sidebar-structure.json" with { type: "json" };

type StarlightSidebar = NonNullable<Parameters<typeof starlight>[0]["sidebar"]>;

type SidebarStructureNode = SidebarStructureGroup | SidebarStructurePage | SidebarStructureExternal;

interface SidebarStructureGroup {
  type: "group";
  label: string;
  collapsed: boolean;
  children: SidebarStructureNode[];
}

interface SidebarStructurePage {
  type: "page";
  label: string;
  path: string;
}

interface SidebarStructureExternal {
  type: "external";
  label: string;
  link: string;
}

/**
 * Turns our own `sidebar-structure.json` structure into a datatype Starlight uses to define the sidebar.
 */
function toStarlightSidebar(items: SidebarStructureNode[]): StarlightSidebar {
  return items.map((item) => {
    if (item.type === "group") {
      return {
        label: item.label,
        collapsed: item.collapsed,
        items: toStarlightSidebar(item.children),
      };
    }

    if (item.type === "page") {
      // Slug reference (path without surrounding slashes): unlike a raw link,
      // Starlight validates it, so a sidebar entry without a matching page
      // fails the build instead of shipping a dead link.
      return { label: item.label, slug: item.path.replace(/^\/+/, "").replace(/\/+$/, "") };
    }

    return {
      label: item.label,
      link: item.link,
    };
  });
}

export const sidebar = toStarlightSidebar(sidebarStructure as SidebarStructureNode[]);
